const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

// The public site: index.html (landing, /), features.html (/features), how-it-works.html (/how-it-works) and help.html (/help).
// They are generated by scripts/build-landing.js (npm run build-landing; the Help words are in scripts/help-content.js,
// and tests/help-site.test.js covers that page in detail); the organiser app is app.html (/app) and
// the sign-in form login.html is shown in a pop-up on the public pages. Static checks, plus the page scripts run in
// a vm with a stubbed browser (the redirect, the pop-up and the embedded sign-in).
const root = path.join(__dirname, '..');
const read = (f) => fs.readFileSync(path.join(root, f), 'utf8');
const { render } = require('../scripts/build-landing');

const PAGES = ['index.html', 'features.html', 'how-it-works.html', 'help.html'];
const rendered = render();
const markup = (s) => s.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<style[\s\S]*?<\/style>/g, '');
const scripts = (s) => [...s.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
const tick = () => new Promise((r) => setImmediate(r));

test('the generator returns exactly the four pages', () => {
  assert.deepEqual(Object.keys(rendered).sort(), PAGES.slice().sort());
});

test('the pages in the repo are the generator output (edit scripts/build-landing.js, then npm run build-landing)', () => {
  PAGES.forEach((p) => {
    assert.ok(fs.existsSync(path.join(root, p)), p + ' exists');
    assert.equal(read(p), rendered[p], p + ' differs from scripts/build-landing.js output; run: npm run build-landing');
  });
});

test('importing the generator writes nothing (it only writes when run directly)', () => {
  const src = read('scripts/build-landing.js');
  assert.match(src, /require\.main === module/);
  assert.match(src, /module\.exports\s*=\s*\{\s*render\s*\}/);
});

test('every page is a complete, titled document with a description and a mobile viewport', () => {
  PAGES.forEach((p) => {
    const h = read(p);
    assert.match(h, /^<!doctype html>/i, p);
    assert.match(h, /<html lang="en">/, p);
    assert.match(h, /<meta name="viewport" content="width=device-width, initial-scale=1">/, p);
    assert.match(h, /<title>[^<]*DartDraw[^<]*<\/title>/, p);
    assert.match(h, /<meta name="description" content="[^"]{20,}">/, p);
    assert.match(h, /<main id="main">/, p);
    assert.match(h, /<a class="skip" href="#main">/, p);
  });
});

test('every page has the login dialog around the sign-in page, and Log in links that open it', () => {
  PAGES.forEach((p) => {
    const h = read(p);
    assert.match(h, /<dialog id="loginDlg"/, p);
    assert.match(h, /<iframe[^>]*id="loginFrame"[^>]*title="[^"]+"[^>]*>/, p + ' iframe with a title');
    assert.ok(h.includes('/login.html?embed=1'), p + ' frames /login.html?embed=1');
    // the iframe is loaded lazily: no src attribute until the dialog first opens
    assert.doesNotMatch(h, /<iframe[^>]*\ssrc=/, p + ' iframe must not load before the dialog opens');
    assert.match(h, /data-src="\/login\.html\?embed=1"/, p);
    // links to the full-page sign-in, so Log in works without JavaScript; the script opens the pop-up instead
    assert.ok((h.match(/<a class="btn[^"]*" href="\/login\.html" data-login>/g) || []).length >= 2, p + ' has Log in links');
    assert.doesNotMatch(h, /<button[^>]*data-login/, p + ' Log in controls are links');
    assert.match(h, /<button[^>]*data-close/, p + ' has a close button');
  });
});

test('the pages link to each other with clean URLs', () => {
  PAGES.forEach((p) => {
    const h = markup(read(p));
    assert.match(h, /href="\/"/, p);
    assert.match(h, /href="\/features"/, p);
    assert.match(h, /href="\/how-it-works"/, p);
    assert.match(h, /href="\/help"/, p);
    assert.doesNotMatch(h, /href="[^"]*(landing|features|how-it-works|help)\.html"/, p + ' links to a .html file name');
  });
});

test('copy: no plan or tier wording, no contact email, no rosters or rubbers, Singles, Doubles and Teams, Group Boards described', () => {
  PAGES.forEach((p) => {
    const h = markup(read(p));
    assert.doesNotMatch(h, /\bTriples?\b|\b(rosters?|rubbers?|handouts?)\b|both players named/i, p);
    assert.doesNotMatch(h, /\bBasic (plan|mode|tier)\b|\bPro (plan|mode|tier)\b|>\s*Pro\s*<|>\s*Basic\s*<|\bpricing\b|\bsubscription\b/i, p);
    assert.doesNotMatch(h, /mailto:|[\w.+-]+@[\w-]+\.[a-z]{2,}/i, p + ' shows an email address');
  });
  assert.match(markup(read('index.html')), /<ul class="tags"[^>]*><li>Singles<\/li><li>Doubles<\/li><li>Teams<\/li><\/ul>/);
  const features = markup(read('features.html'));
  assert.match(features, /<h3>Singles, doubles and teams<\/h3>/);
  // three formats; Group Boards is described as a Knockout option
  const fmt = (features.match(/<div class="fmt">([\s\S]*?)<\/div>\s*<\/div><\/section>/) || [])[1] || '';
  assert.deepEqual([...fmt.matchAll(/<h3>([^<]+)<\/h3>/g)].map((m) => m[1]), ['Round robin', 'Knockout', 'Round robin &rarr; Knockout']);
  assert.match(fmt, /<h3>Knockout<\/h3><p>[^<]*Or Group Boards first/);
  assert.match(features, /Choose Knockout, then Group Boards/);
  assert.match(features, /segments[\s\S]*total legs each team won/);
  assert.match(markup(read('how-it-works.html')), /choose the category and Singles, Doubles or Teams/);
  assert.match(features, /Group Boards/);
  assert.match(features, /<span class="chip">Optional<\/span>/);
  // the app's own wording for the two ways of setting up an event
  assert.match(markup(read('how-it-works.html')), /Basic setup keeps things simple; Advanced adds/);
});

test('how-it-works names the seven steps as the app does, and says Accept & finalize is on step 5', () => {
  const how = markup(read('how-it-works.html'));
  const steps = [...how.matchAll(/<li><span class="num">\d<\/span><div><h3>([^<]+)<\/h3>/g)].map((m) => m[1].replace(/&amp;/g, '&'));
  assert.deepEqual(steps, ['Event creation', 'Format & branding', 'Chart details', 'Confirm & Print Bracket', 'Manage Tournament', 'Finalize Standings', 'Print Final Chart']);
  const app = read('app.html');
  steps.forEach((s) => assert.ok(app.includes(s) || app.includes(s.replace('&', '&amp;')), s + ' is a step name in the app'));
  assert.match(how, /Manage Tournament<\/h3><p>[^<]*click Accept &amp; finalize at the bottom of this step/);
  assert.match(how, /Finalize Standings<\/h3><p>[^<]*read-only/);
  assert.doesNotMatch(how, /Print and accept|QR codes included/);
  // the landing hero: plain Log in, and who makes accounts
  const idx = markup(read('index.html'));
  assert.match(idx, /data-login>Log in <svg/);
  assert.doesNotMatch(idx, /Log in to get started/);
  assert.match(idx, /<p class="cta-note">No account yet\? Accounts are created by the site admin\.<\/p>/);
});

test('only the landing page carries the signed-in check', () => {
  assert.match(scripts(read('index.html')).join('\n'), /fetch\('\/api\/auth\/me'/);
  ['features.html', 'how-it-works.html', 'help.html'].forEach((p) => {
    const js = scripts(read(p)).join('\n');
    assert.doesNotMatch(js, /\/api\/auth\/me/, p);
    assert.doesNotMatch(js, /location\.replace\(target\)/, p);
  });
});

test('the pages stay responsive: breakpoints for phones, wrapping rows, no fixed wide boxes', () => {
  PAGES.forEach((p) => {
    const h = read(p);
    assert.match(h, /@media \(max-width:640px\)/, p);
    assert.match(h, /@media \(max-width:480px\)/, p);
    assert.match(h, /\.wrap\{max-width:1180px;margin:0 auto;padding:0 28px\}/, p);
    assert.match(h, /width:min\(400px,calc\(100vw - 28px\)\)/, p + ' dialog fits a narrow screen');
    assert.match(h, /\.hero-grid\{grid-template-columns:minmax\(0,1fr\);padding-bottom:56px\}/, p + ' single hero column is minmax(0,1fr) (320px overflow)');
    assert.doesNotMatch(h, /\.nav-links\{display:none\}/, p + ' the Features / How it works links stay reachable on phones');
    assert.match(h, /@media \(max-width:480px\)\{\.nav\{height:auto;flex-wrap:wrap/, p + ' header links wrap under the logo on phones');
    // no fixed pixel widths above a phone's width outside the decorative app preview
    assert.doesNotMatch(markup(h), /style="[^"]*width:\s*[5-9]\d\dpx/, p);
  });
});

test('the pages load nothing but the Inter font from another host (help.html also links to the spectators\' help page)', () => {
  const viewerOrigin = new URL(require('../scripts/help-content').VIEWER_URL).origin;
  PAGES.forEach((p) => {
    const hosts = new Set((read(p).match(/https?:\/\/[^/"')\s]+/g) || []));
    hosts.forEach((h) => assert.ok(/^https:\/\/fonts\.(googleapis|gstatic)\.com$/.test(h) || (p === 'help.html' && h === viewerOrigin), p + ' references ' + h));
    // the other host may only be a link the visitor clicks: never a script, style sheet, image or frame
    assert.doesNotMatch(read(p), /<(script|link|img|iframe)[^>]*\s(src|href)="https?:\/\/(?!fonts\.g)/, p);
  });
});

// ---------- routing ----------
test('vercel.json rewrites the clean URLs and keeps the earlier settings', () => {
  const cfg = JSON.parse(read('vercel.json'));
  const rw = (src) => (cfg.rewrites || []).find((r) => r.source === src);
  assert.equal(rw('/app').destination, '/app.html');
  assert.equal(rw('/features').destination, '/features.html');
  assert.equal(rw('/how-it-works').destination, '/how-it-works.html');
  assert.equal(rw('/help').destination, '/help.html');
  assert.deepEqual(cfg.regions, ['sin1']);
  assert.ok(cfg.redirects.some((r) => r.source === '/viewer/:path*'));
});

test('vercel.json: login.html, the app and the account pages can be framed by this site only, and no header is dropped', () => {
  const cfg = JSON.parse(read('vercel.json'));
  const sources = cfg.headers.map((h) => h.source);
  assert.equal(new Set(sources).size, sources.length, 'one rule per path, so no rule overrides another');
  ['/login.html', '/app', '/app.html', '/register.html', '/verify.html', '/forgot.html', '/reset.html'].forEach((src) => {
    const rule = cfg.headers.find((h) => h.source === src);
    assert.ok(rule, 'header rule for ' + src);
    const val = (k) => (rule.headers.find((h) => h.key === k) || {}).value;
    assert.equal(val('Content-Security-Policy'), "frame-ancestors 'self'", src);
    assert.equal(val('X-Frame-Options'), 'SAMEORIGIN', src);
  });
  ['/verify.html', '/reset.html'].forEach((src) => {
    const rule = cfg.headers.find((h) => h.source === src);
    assert.ok(rule.headers.some((h) => h.key === 'Referrer-Policy' && h.value === 'no-referrer'), src + ' keeps Referrer-Policy');
  });
});

test('.vercelignore keeps the design mockups (they hold a fake sign-in form) out of the deployment, and nothing the site needs', () => {
  const lines = read('.vercelignore').split(/\r?\n/).map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
  assert.ok(lines.includes('docs/design/'));
  lines.forEach((l) => assert.doesNotMatch(l, /^(\/?api|\*|\*\.html|\*\.js|\*\.css|viewer|\/?)\/?$/, 'too broad: ' + l));
  PAGES.concat(['app.html', 'login.html']).forEach((p) => assert.doesNotMatch(read(p), /docs\/design/, p));
});

test('package.json has the build-landing script', () => {
  assert.equal(JSON.parse(read('package.json')).scripts['build-landing'], 'node scripts/build-landing.js');
});

// ---------- behaviour: the landing page's signed-in redirect ----------
// Runs the real inline script from the head of index.html against a stub browser.
async function runRedirect({ search = '', hash = '', fetchImpl }) {
  const head = scripts(read('index.html'))[0];
  const calls = { replace: [], fetch: [] };
  const ctx = {
    window: {},
    URLSearchParams,
    Promise,
    location: { search, hash, replace: (u) => calls.replace.push(u) },
    fetch: (url, opts) => { calls.fetch.push({ url, opts }); return fetchImpl(); }
  };
  vm.createContext(ctx);
  vm.runInContext(head, ctx);
  const signedIn = await ctx.window.__ddSignedIn;
  return { calls, signedIn };
}
const meOk = (body) => () => Promise.resolve({ ok: true, status: 200, json: () => Promise.resolve(body) });

test('landing redirect: a signed-in account goes to /app and keeps the query and hash', async () => {
  const r = await runRedirect({ search: '?t=abc&stage=5', hash: '#x', fetchImpl: meOk({ id: 'u1', publicMode: false }) });
  assert.deepEqual(r.calls.replace, ['/app?t=abc&stage=5#x']);
  assert.equal(r.signedIn, true);
  assert.equal(r.calls.fetch[0].url, '/api/auth/me');
  assert.equal(r.calls.fetch[0].opts.credentials, 'same-origin');
  const bare = await runRedirect({ fetchImpl: meOk({ publicMode: false }) });
  assert.deepEqual(bare.calls.replace, ['/app']);
});

test('landing redirect: the login trigger is dropped from the target, other parts kept', async () => {
  const a = await runRedirect({ search: '?login=1&t=abc', hash: '#x', fetchImpl: meOk({ publicMode: false }) });
  assert.deepEqual(a.calls.replace, ['/app?t=abc#x']);
  const b = await runRedirect({ search: '?login=1', hash: '#login', fetchImpl: meOk({ publicMode: false }) });
  assert.deepEqual(b.calls.replace, ['/app']);
});

test('landing redirect: signed out (401), login switched off (publicMode), odd answers and network errors never redirect', async () => {
  const cases = {
    '401': () => Promise.resolve({ ok: false, status: 401, json: () => Promise.resolve({ error: 'no' }) }),
    'public mode': meOk({ id: 'public', publicMode: true }),
    'no publicMode field': meOk({ id: 'u1' }),
    'null body': meOk(null),
    'bad json': () => Promise.resolve({ ok: true, status: 200, json: () => Promise.reject(new Error('bad')) }),
    'network error': () => Promise.reject(new Error('offline'))
  };
  for (const name of Object.keys(cases)) {
    const r = await runRedirect({ search: '?login=1', fetchImpl: cases[name] });
    assert.deepEqual(r.calls.replace, [], name);
    assert.equal(r.signedIn, false, name);
  }
});

test('landing redirect: a hash that looks like another site stays under /app', async () => {
  const r = await runRedirect({ hash: '#//evil.com', fetchImpl: meOk({ publicMode: false }) });
  assert.deepEqual(r.calls.replace, ['/app#//evil.com']);
  const q = await runRedirect({ search: '?next=//evil.com', fetchImpl: meOk({ publicMode: false }) });
  assert.ok(q.calls.replace[0].startsWith('/app?'), q.calls.replace[0]);
});

// ---------- behaviour: the pop-up script ----------
function runDialog(page, { search = '', hash = '', signedIn } = {}) {
  const js = scripts(read(page)).pop();
  const calls = { replaceState: [], reload: 0, listeners: {} };
  const attrs = {};
  const frame = {
    getAttribute: (k) => (k in attrs ? attrs[k] : (k === 'data-src' ? '/login.html?embed=1' : null)),
    setAttribute: (k, v) => { attrs[k] = v; },
    addEventListener: () => {},
    contentWindow: { id: 'frame-window' },
    contentDocument: null,
    style: {}
  };
  const dlgHandlers = {};
  const closeBtn = { addEventListener: (t, fn) => { closeBtn.click = fn; } };
  const dlg = {
    open: false,
    showModal() { this.open = true; },
    close() { this.open = false; },
    setAttribute() {}, removeAttribute() {},
    addEventListener: (t, fn) => { dlgHandlers[t] = fn; },
    querySelector: () => closeBtn
  };
  const loginBtn = { addEventListener: (t, fn) => { loginBtn.click = fn; } };
  const win = { addEventListener: (t, fn) => { calls.listeners[t] = fn; } };
  const ctx = {
    window: win,
    document: {
      getElementById: (id) => (id === 'loginDlg' ? dlg : id === 'loginFrame' ? frame : null),
      querySelectorAll: (sel) => (sel === '[data-login]' ? [loginBtn] : [])
    },
    location: { search, hash, pathname: '/features', reload: () => { calls.reload++; } },
    history: { replaceState: (a, b, url) => calls.replaceState.push(url) },
    URLSearchParams, Promise
  };
  if (signedIn !== undefined) win.__ddSignedIn = Promise.resolve(signedIn);
  vm.createContext(ctx);
  vm.runInContext(js, ctx);
  return { dlg, frame, attrs, calls, loginBtn, closeBtn, dlgHandlers, win, ctx };
}

test('pop-up: nothing opens or loads until asked; a Log in click opens it, loads the iframe once, and is not followed as a link', async () => {
  for (const page of PAGES) {
    const r = runDialog(page);
    await tick();
    assert.equal(r.dlg.open, false, page);
    assert.equal(r.attrs.src, undefined, page + ' iframe not loaded yet');
    assert.deepEqual(r.calls.replaceState, [], page);
    let prevented = false;
    r.loginBtn.click({ preventDefault() { prevented = true; } });
    assert.equal(prevented, true, page + ' click does not navigate to /login.html');
    assert.equal(r.dlg.open, true, page);
    assert.equal(r.attrs.src, '/login.html?embed=1', page);
  }
});

test('pop-up: ?login=1 and #login open it and are removed from the address, other query parts stay', async () => {
  const a = runDialog('features.html', { search: '?login=1&x=1', hash: '#top' });
  await tick();
  assert.equal(a.dlg.open, true);
  assert.equal(a.attrs.src, '/login.html?embed=1');
  assert.deepEqual(a.calls.replaceState, ['/features?x=1#top']);
  const b = runDialog('how-it-works.html', { hash: '#login' });
  await tick();
  assert.equal(b.dlg.open, true);
  assert.deepEqual(b.calls.replaceState, ['/features']);
  const c = runDialog('index.html', { search: '?login=1' });
  await tick();
  assert.equal(c.dlg.open, true);
  assert.deepEqual(c.calls.replaceState, ['/features']);
  const none = runDialog('features.html', { search: '?x=1', hash: '#top' });
  await tick();
  assert.equal(none.dlg.open, false);
  assert.deepEqual(none.calls.replaceState, []);
});

test('pop-up: on the landing page it waits for the signed-in check, and stays shut for a signed-in visitor', async () => {
  const signedOut = runDialog('index.html', { search: '?login=1', signedIn: false });
  assert.equal(signedOut.dlg.open, false, 'not before the answer arrives');
  await tick();
  assert.equal(signedOut.dlg.open, true);
  const signedIn = runDialog('index.html', { search: '?login=1', signedIn: true });
  await tick();
  assert.equal(signedIn.dlg.open, false);
  assert.equal(signedIn.attrs.src, undefined);
});

test('pop-up: closes on the X, a backdrop click and Esc from the sign-in page (same origin and frame only); reloads the form on close', async () => {
  const r = runDialog('features.html', { search: '?login=1' });
  await tick();
  const open = () => { r.dlg.open = true; };
  r.closeBtn.click();
  assert.equal(r.dlg.open, false);
  open();
  r.dlgHandlers.click({ target: {} });
  assert.equal(r.dlg.open, true, 'a click inside the card does not close it');
  r.dlgHandlers.click({ target: r.dlg });
  assert.equal(r.dlg.open, false, 'a click on the backdrop closes it');
  const msg = (origin, source, type) => ({ origin, source, data: { type } });
  const own = 'http://localhost';
  r.ctx.location.origin = own;
  open();
  r.calls.listeners.message(msg('https://evil.example', r.frame.contentWindow, 'dartdraw-close-login'));
  r.calls.listeners.message(msg(own, { other: true }, 'dartdraw-close-login'));
  r.calls.listeners.message(msg(own, r.frame.contentWindow, 'something-else'));
  assert.equal(r.dlg.open, true, 'wrong origin, wrong source or wrong type is ignored');
  r.calls.listeners.message(msg(own, r.frame.contentWindow, 'dartdraw-close-login'));
  assert.equal(r.dlg.open, false);
  // the close event reloads the frame so nothing typed stays in it
  r.attrs.src = '/login.html?embed=1#typed';
  r.dlgHandlers.close();
  assert.equal(r.attrs.src, '/login.html?embed=1');
});

test('pop-up: a page restored from the back/forward cache reloads, so a stale pop-up is never shown', () => {
  const r = runDialog('index.html');
  r.calls.listeners.pageshow({ persisted: false });
  assert.equal(r.calls.reload, 0);
  r.calls.listeners.pageshow({ persisted: true });
  assert.equal(r.calls.reload, 1);
});

// ---------- login.html in the pop-up ----------
function runLogin({ embed, framed = true, loginOk = true, config = { signupOpen: false }, configOk = true }) {
  const js = scripts(read('login.html'))[0];
  const els = {};
  const el = (id) => (els[id] = els[id] || {
    id, value: id === 'email' ? 'a@b.co' : 'secret-pw', hidden: false, textContent: '', className: '', disabled: false,
    addEventListener(t, fn) { (this.handlers = this.handlers || {})[t] = fn; }
  });
  const calls = { top: [], own: [], links: [], parent: [] };
  const anchors = [{}, {}];
  const classes = [];
  const topLoc = { replace: (u) => calls.top.push(u) };
  const ownLoc = { origin: 'http://localhost', search: embed ? '?embed=1' : '', replace: (u) => calls.own.push(u) };
  const win = { location: ownLoc, parent: { postMessage: (m, o) => calls.parent.push([m, o]) } };
  win.top = framed ? { location: topLoc } : win;
  const docHandlers = {};
  const ctx = {
    window: win,
    location: ownLoc,
    URLSearchParams, JSON, Promise,
    document: {
      documentElement: { classList: { add: (c) => classes.push(c) } },
      getElementById: el,
      querySelectorAll: (s) => (s === 'a' ? anchors : []),
      addEventListener: (t, fn) => { docHandlers[t] = fn; }
    },
    fetch: (url) => {
      if (url === '/api/auth/config') return configOk === 'throw' ? Promise.reject(new Error('offline')) : Promise.resolve({ ok: configOk, json: () => Promise.resolve(config) });
      if (url === '/api/auth/login') return Promise.resolve({ ok: loginOk, status: loginOk ? 200 : 401, json: () => Promise.resolve(loginOk ? {} : { error: 'Wrong email or password.' }) });
      return Promise.reject(new Error('unexpected ' + url));
    }
  };
  vm.createContext(ctx);
  vm.runInContext(js, ctx);
  return { els, calls, anchors, classes, docHandlers, el };
}
async function submit(r) {
  await r.els.loginForm.handlers.submit({ preventDefault() {} });
}

test('login.html embedded: styles itself for the pop-up, links open the whole window, and a good sign-in sends the TOP window to /app', async () => {
  const r = runLogin({ embed: true });
  assert.deepEqual(r.classes, ['embed']);
  assert.deepEqual(r.anchors.map((a) => a.target), ['_top', '_top']);
  await submit(r);
  assert.deepEqual(r.calls.top, ['/app']);
  assert.deepEqual(r.calls.own, []);
});

test('login.html embedded: Esc asks the parent page (same origin only) to close the pop-up', () => {
  const r = runLogin({ embed: true });
  r.docHandlers.keydown({ key: 'a' });
  assert.deepEqual(r.calls.parent, []);
  r.docHandlers.keydown({ key: 'Escape' });
  assert.equal(r.calls.parent.length, 1);
  assert.equal(r.calls.parent[0][0].type, 'dartdraw-close-login');
  assert.equal(r.calls.parent[0][1], 'http://localhost', 'targetOrigin is the page origin, never "*"');
});

test('login.html opened on its own (or ?embed=1 outside a frame): normal page, sends the window itself to /app', async () => {
  const plain = runLogin({ embed: false, framed: false });
  assert.deepEqual(plain.classes, []);
  await submit(plain);
  assert.deepEqual(plain.calls.own, ['/app']);
  assert.deepEqual(plain.calls.top, []);
  const notFramed = runLogin({ embed: true, framed: false });
  assert.deepEqual(notFramed.classes, [], 'embed styling needs a real frame');
  await submit(notFramed);
  assert.deepEqual(notFramed.calls.own, ['/app']);
});

test('login.html: a failed sign-in shows the message and goes nowhere', async () => {
  const r = runLogin({ embed: true, loginOk: false });
  await submit(r);
  assert.deepEqual(r.calls.top.concat(r.calls.own), []);
  assert.equal(r.els.msg.textContent, 'Wrong email or password.');
});

// ---------- "No account yet?" and the Admin's contact line ----------
const settle = async () => { for (let i = 0; i < 5; i++) await new Promise((r) => setImmediate(r)); };

test('login.html: "No account yet?" is in the page as written (works without JavaScript), with an empty hidden contact line', () => {
  const m = read('login.html').replace(/<script[\s\S]*?<\/script>/g, '').replace(/<style[\s\S]*?<\/style>/g, '');
  assert.match(m, /<div class="foot noacct" id="noAccountFoot"><b>No account yet\?<\/b> Accounts are created by the site admin\.<span class="contact" id="adminContact" hidden><\/span><\/div>/);
  assert.doesNotMatch(m, /id="noAccountFoot"[^>]*hidden/);
  assert.match(read('login.html'), /\[hidden\]\{display:none!important\}/, 'hidden wins over the contact line display rule');
});

test('login.html: with a contact line set, it is shown under "No account yet?" as text', async () => {
  const r = runLogin({ embed: true, config: { signupOpen: false, adminContact: 'Ask the club secretary at the bar.' } });
  await settle();
  assert.equal(r.els.adminContact.textContent, 'Ask the club secretary at the bar.');
  assert.equal(r.els.adminContact.hidden, false);
  assert.equal(r.el('noAccountFoot').hidden, false);
});

test('login.html: with no contact line (empty, missing, not text) only the first sentence shows', async () => {
  for (const config of [{ signupOpen: false, adminContact: '' }, { signupOpen: false, adminContact: '   ' }, { signupOpen: false }, { signupOpen: false, adminContact: 42 }, { signupOpen: false, adminContact: { a: 1 } }]) {
    const r = runLogin({ embed: false, framed: false, config });
    await settle();
    assert.equal(r.els.adminContact.hidden, true, JSON.stringify(config));
    assert.equal(r.els.adminContact.textContent, '');
    assert.equal(r.el('noAccountFoot').hidden, false);
  }
  // the check failing (server error, or offline) leaves the note as it is in the page
  for (const configOk of [false, 'throw']) {
    const r = runLogin({ embed: false, framed: false, configOk });
    await settle();
    assert.equal(r.el('noAccountFoot').hidden, false);
    assert.equal(r.el('adminContact').textContent, '');
  }
});

test('login.html: the contact line can never become markup (textContent only, at most 200 characters)', async () => {
  const evil = '<img src=x onerror=alert(1)><script>alert(2)</script>';
  const r = runLogin({ embed: true, config: { signupOpen: false, adminContact: evil + 'x'.repeat(300) } });
  await settle();
  assert.equal(r.els.adminContact.textContent, (evil + 'x'.repeat(300)).slice(0, 200), 'set as text, cut to 200');
  assert.equal(r.els.adminContact.innerHTML, undefined, 'innerHTML is never touched');
  const js = scripts(read('login.html'))[0];
  assert.doesNotMatch(js, /innerHTML|insertAdjacentHTML|outerHTML|document\.write/);
});

test('login.html: while sign-up is open the Sign up link replaces "No account yet?"', async () => {
  const r = runLogin({ embed: true, config: { signupOpen: true, adminContact: 'Ask Sam.' } });
  await settle();
  assert.equal(r.el('signupFoot').hidden, false);
  assert.equal(r.el('noAccountFoot').hidden, true);
});

test('login.html has the embed styles', () => {
  const h = read('login.html');
  assert.match(h, /html\.embed body\{[^}]*background:transparent/);
  assert.match(h, /html\.embed \.card\{[^}]*box-shadow:none/);
  assert.doesNotMatch(scripts(h)[0], /location\.href\s*=\s*'\/'/);
});

test('the account pages send people back to the pop-up with /?login=1', () => {
  ['register.html', 'verify.html', 'forgot.html', 'reset.html'].forEach((p) => {
    assert.match(read(p), /href="\/\?login=1"/, p);
    assert.doesNotMatch(read(p), /href="\/login\.html"/, p);
  });
});

// ---------- the app moved to app.html ----------
test('app.html is the organiser app and index.html is not', () => {
  const app = read('app.html');
  assert.match(app, /<script src="render\.js"><\/script>/);
  assert.match(app, /window\.onload = async function\(\)/);
  assert.match(app, /async function apiFetch\(/);
  assert.match(app, /id="printSheets"/);
  const landing = read('index.html');
  assert.doesNotMatch(landing, /apiFetch|window\.onload|id="printSheets"|src="render\.js"/);
  assert.ok(landing.length < app.length / 5, 'the landing page is small next to the app');
});

test('app.html sends signed-out users to the login pop-up (replace, so Back does not loop) and keeps its popout and deep-link behaviour', () => {
  const app = read('app.html');
  assert.match(app, /res\.status===401\)\{ window\.location\.replace\('\/\?login=1'\)/);
  assert.match(app, /async function logout\(\)\{[\s\S]{0,200}?window\.location\.replace\('\/\?login=1'\);/);
  assert.match(app, /if\(!meRes\.ok\)\{ window\.location\.replace\('\/\?login=1'\); return; \}/);
  assert.match(app, /catch\(e\)\{ window\.location\.replace\('\/\?login=1'\); return; \}/);
  assert.equal((app.match(/'\/\?login=1'/g) || []).length, 4);
  assert.doesNotMatch(app, /location\.href\s*=\s*'\/\?login=1'/);
  assert.doesNotMatch(app, /login\.html/, 'no redirect to /login.html remains');
  // the popout window reuses whatever path the app was opened at (/app) and the deep link reads location.search
  assert.ok(app.includes("location.origin + location.pathname + '?t='"), 'popout URL follows location.pathname');
  assert.match(app, /URLSearchParams\(location\.search\)/);
});
